import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';

const partners = [
  { name: 'Partner A', logo: 'https://via.placeholder.com/150x80?text=Partner+A' },
  { name: 'Partner B', logo: 'https://via.placeholder.com/150x80?text=Partner+B' },
];

function Home() {
  const sectionRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);
  const partnersRef = useRef(null);
const [partnersVisible, setPartnersVisible] = useState(false);
useEffect(() => {
  const observer = new IntersectionObserver(
    entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          setPartnersVisible(true);
          observer.disconnect();
        }
      });
    },
    { threshold: 0.3 }
  );

  if (partnersRef.current) {
    observer.observe(partnersRef.current);
  }

  return () => observer.disconnect();
}, []);


  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.disconnect(); // Remove after first trigger
          }
        });
      },
      { threshold: 0.3 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <section id="home" ref={sectionRef} className={`hero ${isVisible ? 'visible' : ''}`}>
      <div className="container hero-inner">
        <div className="hero-copy">
          <h1>Your Space Can Now Listen, Learn and Respond!</h1>
          <p className="lead">
            Smart home & building automation solutions that make everyday living intelligent, efficient and secure.
          </p>
          <Link className="btn" to="/products">Our Products</Link>
        </div>
        <div className="hero-media">
          <img
            src="https://images.unsplash.com/photo-1506765515384-028b60a970df?q=80&w=1200&auto=format&fit=crop&ixlib=rb-4.0.3&s=placeholder"
            alt="Smart home"
          />
        </div>
      </div>
    <section ref={sectionRef} className={`features fade-in-section ${isVisible ? 'visible' : ''}`}>
      <div className="feature-block">
        <div className="text">
          <h2>Innovative Solutions</h2>
          <p>
            At Kilowatt Electric, we specialize in smart home and building automation solutions designed to make everyday living more intelligent, efficient, and secure. Our systems seamlessly integrate lighting, climate control, security, entertainment, energy management, and more—delivering unmatched convenience and control at your fingertips.
          </p>
        </div>
        <img src="https://via.placeholder.com/400x300" alt="Modern Kitchen" />
      </div>

      <div className="feature-block">
        <img src="https://via.placeholder.com/400x300" alt="Dining Room" />
        <div className="text">
          <h2>Seamless Integration</h2>
          <p>
            Whether it’s a private home, commercial space, hotel, or healthcare facility, we customize each solution to suit your unique needs, ensuring comfort, sustainability, and future-ready technology. With a focus on intuitive design and reliable performance, we help you create smarter spaces that adapt to your lifestyle or business operations—while reducing energy costs and increasing property value.
          </p>
        </div>
      </div>
    </section>
    <section
  ref={partnersRef}
  className={`partners-section fade-in-section ${partnersVisible ? 'visible' : ''}`}
>
  <h2 className="partners-title">Our Partners</h2>
  <div className="partners-logos">
    {partners.map((partner, index) => (
      <div className="partner-card" key={index}>
        <img src={partner.logo} alt={partner.name} />
      </div>
    ))}
  </div>
</section>
</section>
  );
}
export default Home;
